8:   if (Platform.OS !== "android") throw new Error("File export is available on Android only.");
9:   const backup = exportData(data);
10:   const permission = await FileSystem.StorageAccessFramework.requestDirectoryPermissionsAsync();
11:   if (!permission.granted) return "Backup canceled. Nothing was exported.";
12:   const stamp = new Date().toISOString().replace(/[:.]/g, "-");
13:   let uri: string | null = null;
14:   try {
15:     uri = await FileSystem.StorageAccessFramework.createFileAsync(
16:       permission.directoryUri,
17:       `CasitaDex-backup-${stamp}`,
18:       "application/json",
19:     );
20:     await FileSystem.writeAsStringAsync(uri, backup, { encoding: FileSystem.EncodingType.UTF8 });
21:     const check = await FileSystem.readAsStringAsync(uri, { encoding: FileSystem.EncodingType.UTF8 });
22:     if (check !== backup || exportData(parseData(check)) !== backup) {
23:       throw new Error("Backup read-back verification failed.");
24:     }
25:     return "Backup saved and verified in the selected folder. Keep an independent second copy.";
26:   } catch (error) {
27:     let cleanup = "";
28:     if (uri) {
29:       try {
30:         await FileSystem.deleteAsync(uri, { idempotent: true });
31:       } catch {
32:         cleanup = " A possibly incomplete file may remain in your chosen folder; delete it manually.";
33:       }
34:     }
35:     const detail = error instanceof Error ? error.message : "File provider failure";
36:     throw new Error(`Backup did not complete: ${detail}. Do not rely on this export.${cleanup}`);
37:   }
38: }
