41: export async function pickBackupFile(): Promise<string | null> {
42:   if (Platform.OS !== "android") throw new Error("File import is available on Android only.");
43:   const picked = await DocumentPicker.getDocumentAsync({
44:     copyToCacheDirectory: true,
45:     multiple: false,
46:     type: ["application/json", "text/plain", "application/octet-stream"],
47:   });
48:   if (picked.canceled) return null;
49:   const asset = picked.assets[0];
50:   if (!asset) throw new Error("No backup file was selected.");
51:   if (asset.size !== undefined && asset.size > 2_000_000) {
52:     throw new Error("Backup is too large. Maximum size is 2 MB.");
53:   }
54:   const raw = await FileSystem.readAsStringAsync(asset.uri, { encoding: FileSystem.EncodingType.UTF8 });
55:   if (new TextEncoder().encode(raw).byteLength > 2_000_000) {
56:     throw new Error("Backup is too large. Maximum size is 2 MB.");
57:   }
58:   return exportData(parseData(raw));
59: }

